        .hero-title {
            text-align: center;
            margin-bottom: 30px;
        }
        
        .hero-title h1 {
            font-size: 34px;
            font-weight: 700;
            line-height: 1.4;
            color:#000000;
            margin-bottom: 5px;
        }
        
