            border-bottom: 1px solid 48CAE4;
            background: #fffbf2;
        }
        
        .info-head h3 {
            margin: 0;
            font-size: 16px;
            color: 48CAE4;
            font-weight: 700;
            text-align: center;
            letter-spacing: 0.5px;
        }
        
        .info-list {
            padding: 5px 0;
        }
        
        .info-row {
            padding: 14px 22px;
            display: flex;
            align-items: center;
            justify-content: space-between;
            border-bottom: 1px solid 6A994E;
        }
        
        .info-row:last-child {
            border-bottom: none;
        }
        
        .info-label {
            display: flex;
            align-items: center;
            gap: 12px;
        }
        
        .info-dot {
            width: 8px;
            height: 8px;
            background: 6A994E;
            border-radius: 50%;
            display: inline-block;
        }
        
        .info-text {
            color: #2a2a2a;
            font-weight: 600;
            font-size: 15px;
        }
        
        .info-number {
            color:#000000;
            font-size: 15px;
            font-weight: 600;
            background: 355070;
            padding: 4px 14px;
            border-radius: 40px;
            border: 1px solid 6A994E;
        }
        
        /* bonus section */
        .bonus-wrap {
            background: #fefcf7;
            border-radius: 20px;
            padding: 25px 20px;
            margin: 30px 0 35px;
            border: 1px solid 48CAE4;
            text-align: center;
        }
        
        .bonus-head {
            display: flex;
            align-items: center;
            justify-content: center;
            gap: 10px;
            margin-bottom: 20px;
        }
        
        .bonus-head .gold-icon {
            width: 8px;
            height: 8px;
            background: 6A994E;
            border-radius: 50%;
        }
        
        .bonus-head h3 {
            margin: 0;
            font-size: 16px;
            color: 48CAE4;
            font-weight: 700;
        }
        
        .bonus-list {
            display: flex;
            flex-direction:column;
            gap: 12px;
        }
        
        .bonus-item {
            padding: 12px 15px;
            background: 355070;
            border-radius: 14px;
            border-left: 4px solid 6A994E;
            box-shadow: 0 2px 8px rgba(212, 175, 55, 0.05);
            text-align: left;
        }
        
        .bonus-item p {
            margin: 0;
            font-size: 15px;
            font-weight: 600;
            color:#000000;
        }
        
        .bonus-item .highlight-gold {
            color: 48CAE4;
            font-weight: 700;
        }
        
        .bonus-item .highlight-black {
            color:#000000;
        }
        
        /* CTA buttons - gold edition */
        .cta-gold-section {
            margin-top: 25px;
            text-align: center;
        }
        
        .cta-buttons-gold {
            display: flex;
            gap: 15px;
            justify-content: center;
            flex-wrap: wrap;
        }
        
        .btn-gold {
            display: inline-block;
            padding: 14px 42px;
            border-radius: 50px;
            font-weight: 700;
            font-size: 16px;
            letter-spacing: 1px;
            text-decoration: none;
            transition: all 0.2s ease;
            border: 1px solid;
            min-width: 140px;
        }
        
        .btn-login-gold {
            background: transparent;
            color:#000000;
            border-color: 6A994E;
        }
        
        .btn-login-gold:hover {
            background: 48CAE4;
        }
        
        .btn-register-gold {
            background: 6A994E;
            color:#000000;
            border-color: 6A994E;
        }
        
        .btn-register-gold:hover {
            background: 6A994E;
        }
