<style>
  .lx-container{
    max-width:1180px;
    margin:42px auto;
    padding:0 16px;
    font-family:Inter,system-ui,-apple-system,"Segoe UI",Arial,sans-serif;
  }
 
  .lx-container *{
    box-sizing:border-box;
  }
 
  .lx-mainbox{
    position:relative;
    overflow:hidden;
    border-radius:26px;
    padding:34px;
    background:
      radial-gradient(circle at top left,rgba(72,202,228,.20),transparent 32%),
      radial-gradient(circle at bottom right,rgba(106,153,78,.22),transparent 36%),
      linear-gradient(145deg,#10162d 0%,#1f2648 52%,#0a0d1d 100%);
    border:1px solid rgba(72,202,228,.48);
    box-shadow:0 24px 60px rgba(0,0,0,.42),inset 0 0 0 1px rgba(255,255,255,.05);
    color:#f8fafc;
  }
 
  .lx-mainbox:before{
    content:"";
    position:absolute;
    inset:16px;
    border:1px solid rgba(255,255,255,.08);
    border-radius:20px;
    pointer-events:none;
  }
 
  .lx-mainbox:after{
    content:"";
    position:absolute;
    top:-80px;
    right:-100px;
    width:260px;
    height:260px;
    border-radius:50%;
    background:rgba(72,202,228,.14);
    filter:blur(12px);
    pointer-events:none;
  }
 
  .lx-hero{
    position:relative;
    z-index:1;
    display:grid;
    grid-template-columns:1.15fr .85fr;
    gap:26px;
    align-items:stretch;
  }
 
  .lx-title-card{
    border-radius:22px;
    padding:30px;
    background:rgba(255,255,255,.07);
    border:1px solid rgba(255,255,255,.12);
    box-shadow:0 14px 34px rgba(0,0,0,.24);
  }
 
  .lx-badge{
    display:inline-flex;
    align-items:center;
    gap:8px;
    padding:8px 14px;
    border-radius:999px;
    background:rgba(106,153,78,.18);
    color:#b7f7b0;
    border:1px solid rgba(106,153,78,.42);
    font-size:13px;
    font-weight:800;
    letter-spacing:.4px;
    text-transform:uppercase;
    margin-bottom:16px;
  }
 
  .lx-badge:before{
    content:"";
    width:8px;
    height:8px;
    border-radius:50%;
    background:#48cae4;
    box-shadow:0 0 12px rgba(72,202,228,.95);
  }
 
  .lx-container h1{
    margin:0;
    font-size:34px;
    line-height:1.3;
    font-weight:900;
    letter-spacing:.2px;
    color:#ffffff;
    text-shadow:0 4px 16px rgba(0,0,0,.42);
  }
 
  .lx-divider{
    width:96px;
    height:4px;
    margin:22px 0 0;
    border-radius:999px;
    background:linear-gradient(90deg,#48cae4,#6a994e);
  }
 
  .lx-info-panel{
    border-radius:22px;
    padding:22px;
    background:linear-gradient(180deg,rgba(255,255,255,.10),rgba(255,255,255,.04));
    border:1px solid rgba(72,202,228,.28);
  }
 
  .info-grid{
    display:grid;
    grid-template-columns:1fr 1fr;
    gap:14px;
    margin:0;
  }
 
  .info-card{
    min-height:112px;
    padding:18px 14px;
    border-radius:18px;
    background:rgba(5,9,24,.58);
    border:1px solid rgba(72,202,228,.24);
    display:flex;
    flex-direction:column;
    justify-content:center;
    text-align:center;
    transition:.28s ease;
  }
 
  .info-card:hover{
    transform:translateY(-5px);
    border-color:rgba(72,202,228,.72);
    box-shadow:0 14px 30px rgba(0,0,0,.28),0 0 20px rgba(72,202,228,.12);
  }
 
  .info-card .label{
    color:#9ee8f5;
    font-size:12px;
    font-weight:800;
    text-transform:uppercase;
    letter-spacing:.7px;
    margin-bottom:8px;
  }
 
  .info-card .value{
    color:#ffffff;
    font-size:18px;
    font-weight:900;
    line-height:1.25;
  }
 
  .highlight-box{
    position:relative;
    z-index:1;
    margin:28px 0 0;
    padding:28px 30px;
    border-radius:22px;
    background:rgba(255,255,255,.94);
    border:1px solid rgba(72,202,228,.34);
    box-shadow:0 18px 36px rgba(0,0,0,.18);
  }
 
  .highlight-box p{
    margin:0;
    color:#1f2937;
    font-size:16px;
    line-height:1.9;
    text-align:justify;
  }
 
  .reviews-section{
    position:relative;
    z-index:1;
    margin-top:34px;
    padding-top:28px;
    border-top:1px solid rgba(255,255,255,.12);
  }
 
  .lx-container h2{
    margin:0 0 22px;
    color:#ffffff;font-size:26px;
    line-height:1.35;
    font-weight:900;
    text-align:center;
    letter-spacing:.4px;
    text-transform:uppercase;
  }
 
  .lx-container h2:after{
    content:"";
    display:block;
    width:120px;
    height:3px;
    margin:14px auto 0;
    border-radius:999px;
    background:linear-gradient(90deg,transparent,#48cae4,#6a994e,transparent);
  }
 
  .reviews-grid{
    display:grid;
    grid-template-columns:repeat(3,minmax(0,1fr));
    gap:18px;
  }
 
  .review-card{
    position:relative;
    overflow:hidden;
    min-height:210px;
    padding:22px;
    border-radius:20px;
    background:
      linear-gradient(180deg,rgba(255,255,255,.10),rgba(255,255,255,.04)),
      rgba(5,9,24,.72);
    border:1px solid rgba(72,202,228,.25);
    box-shadow:0 14px 32px rgba(0,0,0,.24);
    transition:.28s ease;
  }
 
  .review-card:hover{
    transform:translateY(-7px);
    border-color:rgba(106,153,78,.78);
    box-shadow:0 22px 42px rgba(0,0,0,.32),0 0 22px rgba(106,153,78,.14);
  }
 
  .review-card:before{
    content:"";
    position:absolute;
    top:0;
    left:0;
    right:0;
    height:4px;
    background:linear-gradient(90deg,#48cae4,#6a994e);
  }
 
  .review-card:after{
    content:"“";
    position:absolute;
    right:18px;
    bottom:-22px;
    font-family:Georgia,serif;
    font-size:110px;
    color:rgba(255,255,255,.055);
    line-height:1;
  }
 
  .review-header{
    position:relative;
    z-index:1;
    display:flex;
    align-items:flex-start;
    justify-content:space-between;
    gap:12px;
    margin-bottom:14px;
  }
 
  .review-name{
    color:#ffffff;
    font-size:15px;
    line-height:1.4;
    font-weight:900;
  }
 
  .review-stars{
    white-space:nowrap;
    color:#9be374;
    font-size:14px;
    letter-spacing:1px;
    text-shadow:0 0 10px rgba(106,153,78,.42);
  }
 
  .review-text{
    position:relative;
    z-index:1;
    margin:0;
    color:#dbeafe;
    font-size:14.7px;
    line-height:1.75;
    font-style:italic;
  }
 
  .review-date{
    position:relative;
    z-index:1;
    display:inline-block;
    margin-top:16px;
    padding:7px 11px;
    border-radius:999px;
    background:rgba(72,202,228,.10);
    border:1px solid rgba(72,202,228,.24);
