<style>
  .mahjong-ways-thailand{
    margin:0;
    padding:0;
    font-family:"Poppins","Segoe UI",Arial,sans-serif;
    background:transparent;
    color:#eafcff;
  }
 
  .popup-overlay{
    position:fixed;
    inset:0;
    width:100vw;
    height:100vh;
    display:flex;
    align-items:center;
    justify-content:center;
    padding:18px;
    background:
      radial-gradient(circle at 20% 20%,rgba(72,202,228,.22),transparent 32%),
      radial-gradient(circle at 80% 85%,rgba(106,153,78,.25),transparent 34%),
      rgba(3,7,18,.72);
    backdrop-filter:blur(7px);
    -webkit-backdrop-filter:blur(7px);
    z-index:9999;
  }
 
  .popup-container{
    position:relative;
    width:min(92vw,430px);
    border-radius:28px;
    overflow:hidden;
    text-align:center;
    background:
      linear-gradient(180deg,rgba(255,255,255,.10),rgba(255,255,255,.035)),
      linear-gradient(145deg,#07111f 0%,#111b34 50%,#050912 100%);
    border:1px solid rgba(72,202,228,.42);
    box-shadow:
      0 30px 80px rgba(0,0,0,.70),
      0 0 0 1px rgba(255,255,255,.05) inset,
      0 0 42px rgba(72,202,228,.18);
    animation:popupRise .65s cubic-bezier(.2,.8,.2,1) both,popupAura 4s ease-in-out infinite;
  }
 
  @keyframes popupRise{
    0%{opacity:0;transform:translateY(34px) scale(.92)}
    100%{opacity:1;transform:translateY(0) scale(1)}
  }
 
  @keyframes popupAura{
    0%,100%{box-shadow:0 30px 80px rgba(0,0,0,.70),0 0 0 1px rgba(255,255,255,.05) inset,0 0 34px rgba(72,202,228,.16)}
    50%{box-shadow:0 30px 80px rgba(0,0,0,.70),0 0 0 1px rgba(255,255,255,.05) inset,0 0 54px rgba(106,153,78,.24)}
  }
 
  .popup-container:before{
    content:"";
    position:absolute;
    inset:12px;
    border-radius:22px;
    border:1px solid rgba(255,255,255,.08);
    pointer-events:none;
    z-index:4;
  }
 
  .popup-container:after{
    content:"";
    position:absolute;
    top:-45%;
    left:-80%;
    width:70%;
    height:190%;
    background:linear-gradient(115deg,transparent 35%,rgba(255,255,255,.18) 50%,transparent 65%);
    transform:rotate(8deg);
    animation:softSweep 5.2s ease-in-out infinite;
    pointer-events:none;
    z-index:5;
  }
 
  @keyframes softSweep{
    0%{left:-85%}
    45%{left:115%}
    100%{left:115%}
  }
 
  .close-btn{
    position:absolute;
    top:14px;
    right:14px;
    width:34px;
    height:34px;
    border-radius:12px;
    background:rgba(3,7,18,.72);
    border:1px solid rgba(72,202,228,.38);
    cursor:pointer;
    z-index:20;
    display:grid;
    place-items:center;
    transition:.25s ease;
    box-shadow:0 8px 20px rgba(0,0,0,.35);
